<?php declare(strict_types=1);
/** Scoped controls; profile definitions and human values remain original. */
$wfI??=static fn(string $source):string=>$source;
$wfF??=static function(string $source,array $values)use($wfI):string{$arguments=[];foreach($values as$key=>$value)$arguments['{'.$key.'}']=(string)$value;return strtr($wfI($source),$arguments);};
$wfHidden??=static fn(string $key,mixed $value):string=>'<input type="hidden" name="'.$wfEsc($key).'" value="'.$wfEsc($value).'">';

$wfRegisterColumns=['category'=>'Gefährdungskategorie','hazard'=>'Gefährdung','impact'=>'Auswirkung','controls'=>'Schutzmaßnahmen','responsible'=>'Verantwortlich','effectiveness'=>'Wirksamkeitsprüfung'];
$wfRegisterLimits=\Kulturhus\Verein\DocumentWorkflow\RiskRegister::TEXT_LIMITS;
$wfRegisterRow=static function(string $name,int|string $index,array $row,bool $editable,string $profile='',int $total=0,string $fieldKey='')use($wfEsc,$wfRegisterColumns,$wfRegisterLimits,$wfI,$wfF,$wfHidden):void{
 $number=is_int($index)?(string)($index+1):'__ROW_NUMBER__';$origin=is_string($row['__origin']??null)?$row['__origin']:(is_int($index)?(string)$index:'');
 $textCell=static function(string $column)use($name,$index,$row,$editable,$wfEsc,$wfRegisterColumns,$wfRegisterLimits,$number,$wfI,$wfF):void{?>
 <td class="dwf-register-text-cell" data-dwf-column="<?= $wfEsc($column) ?>"><span class="dwf-register-cell-label"><?= $wfEsc($wfI($wfRegisterColumns[$column])) ?></span><textarea class="form-control" rows="4" name="<?= $wfEsc($name.'['.$index.']['.$column.']') ?>" data-dwf-character-limit="<?= $wfRegisterLimits[$column] ?>" aria-label="<?= $wfEsc($wfF('Zeile {row}: {column}',['row'=>$number,'column'=>$wfI($wfRegisterColumns[$column])])) ?>" data-dwf-register-path="<?= $wfEsc($column) ?>" data-dwf-column-label="<?= $wfEsc($wfI($wfRegisterColumns[$column])) ?>" <?= !$editable?'disabled':'' ?>><?= $wfEsc($row[$column]??'') ?></textarea><small><?= $wfEsc($wfF('Bis zu {count} Zeichen.',['count'=>$wfRegisterLimits[$column]])) ?></small>
 <?php if($column==='controls'):foreach(\Kulturhus\Verein\DocumentWorkflow\RiskRegister::DATE_LABELS as$key=>$label):$date=is_string($row[$key]??null)?$row[$key]:'';$valid=$date===''||\Kulturhus\Verein\DocumentWorkflow\WorkflowDeadlines::validDate($date);?><label class="dwf-register-date"><?= $wfEsc($wfI($label)) ?><input class="form-control" type="<?= $valid?'date':'text' ?>" name="<?= $wfEsc($name.'['.$index.']['.$key.']') ?>" value="<?= $wfEsc($date) ?>" aria-label="<?= $wfEsc($wfF('Zeile {row}: {column}',['row'=>$number,'column'=>$wfI($label)])) ?>" data-dwf-register-path="<?= $wfEsc($key) ?>" data-dwf-column-label="<?= $wfEsc($wfI($label)) ?>" <?= !$editable?'disabled':'' ?>></label><?php endforeach;endif ?></td>
 <?php };
 $riskCells=static function(string $column,string $label)use($name,$index,$row,$editable,$wfEsc,$number,$profile,$wfI,$wfF):void{
  $risk=is_array($row[$column]??null)?$row[$column]:[];
  foreach(['severity'=>'Schadensschwere S','likelihood'=>'Wahrscheinlichkeit L']as$axis=>$axisLabel):$selected=is_scalar($risk[$axis]??null)?(string)$risk[$axis]:'';?>
  <td class="dwf-register-risk-cell"><span class="dwf-register-cell-label"><?= $wfEsc($wfI($label).' · '.$wfI($axisLabel)) ?></span><select class="form-control" name="<?= $wfEsc($name.'['.$index.']['.$column.']['.$axis.']') ?>" aria-label="<?= $wfEsc($wfF('Zeile {row}: {column}',['row'=>$number,'column'=>$wfI($label).' '.$wfI($axisLabel)])) ?>" data-dwf-register-path="<?= $wfEsc($column.']['.$axis) ?>" data-dwf-column-label="<?= $wfEsc($wfI($label).' '.$wfI($axisLabel)) ?>" <?= !$editable?'disabled':'' ?>><option value="">–</option><?php if($selected!==''&&!preg_match('/\A[1-5]\z/D',$selected)):?><option value="<?= $wfEsc($selected) ?>" selected><?= $wfEsc($wfF('Stufe prüfen: {value}',['value'=>$selected])) ?></option><?php endif;for($level=1;$level<=5;$level++):?><option value="<?= $level ?>" <?= $selected===(string)$level?'selected':'' ?>><?= $axis==='severity'?chr(64+$level):$level ?></option><?php endfor ?></select></td>
  <?php endforeach;
  $complete=isset($risk['severity'],$risk['likelihood'])&&is_scalar($risk['severity'])&&is_scalar($risk['likelihood'])&&preg_match('/^[1-5]$/D',(string)$risk['severity'])&&preg_match('/^[1-5]$/D',(string)$risk['likelihood']);$band=$complete?\Kulturhus\Verein\DocumentWorkflow\RiskProfiles::bandFor((int)$risk['severity']*(int)$risk['likelihood'],$profile):null;?>
  <td class="dwf-register-risk-cell"><span class="dwf-register-cell-label"><?= $wfEsc($wfI($label).' · '.$wfI('Risikowert')) ?></span><output class="<?= $band?'dwf-risk-band-'.$wfEsc($band['key']):'' ?>" data-dwf-register-score="<?= $wfEsc($column) ?>" aria-label="<?= $wfEsc($wfI($label).' '.$wfI('Risikowert').($band?' · '.$band['label']:'')) ?>"><?= $complete?(int)$risk['severity']*(int)$risk['likelihood']:'–' ?><?php if($band):?><small><?= $wfEsc($band['label']) ?></small><?php endif ?></output></td>
 <?php };
 ?><tr data-dwf-register-row><th scope="row"><span><?= $wfEsc($wfI('Gefährdung')) ?> <span data-dwf-row-number><?= $wfEsc($number) ?></span></span><?php if($editable):echo '<input type="hidden" data-dwf-register-origin name="'.$wfEsc($name.'['.$index.'][__origin]').'" value="'.$wfEsc($origin).'">';?><div class="dwf-register-row-actions"><button type="submit" formnovalidate name="wf_edit" value="register_up:<?= $wfEsc($fieldKey.':'.$index) ?>" class="btn btn-outline theme-secondary secondary" data-dwf-register-move="up" <?= !is_int($index)||$index===0?'disabled':'' ?> aria-label="<?= $wfEsc($wfI('Zeile nach oben')) ?>">↑</button><button type="submit" formnovalidate name="wf_edit" value="register_down:<?= $wfEsc($fieldKey.':'.$index) ?>" class="btn btn-outline theme-secondary secondary" data-dwf-register-move="down" <?= !is_int($index)||$index>=$total-1?'disabled':'' ?> aria-label="<?= $wfEsc($wfI('Zeile nach unten')) ?>">↓</button><button type="submit" formnovalidate name="wf_edit" value="register_remove:<?= $wfEsc($fieldKey.':'.$index) ?>" class="btn btn-outline theme-secondary secondary" data-dwf-register-remove aria-label="<?= $wfEsc($wfI('Zeile entfernen')) ?>">×</button></div><?php endif ?></th><?php
 $textCell('category');$textCell('hazard');$textCell('impact');$riskCells('initial','Ausgangsrisiko');$textCell('controls');$riskCells('residual','Restrisiko');$textCell('responsible');$textCell('effectiveness');?></tr><?php
};
$wfRegister=static function(string $name,mixed $value,bool $editable,string $profile='',string $fieldKey='')use($wfEsc,$wfRegisterRow,$wfI,$wfF,$wfHidden):void{
 $profile=$profile!==''?$profile:\Kulturhus\Verein\DocumentWorkflow\RiskProfiles::RWE_DE;
 $registerRows=is_array($value)?array_values(array_filter($value,'is_array')):[];if($fieldKey===''&&preg_match('/\Awf_values\[([a-z][a-z0-9_]{0,63})\]\z/D',$name,$match))$fieldKey=$match[1];?>
 <section class="dwf-register-editor" data-dwf-register data-dwf-matrix-profile="<?= $wfEsc($profile) ?>" data-dwf-register-name="<?= $wfEsc($name) ?>" data-dwf-register-field="<?= $wfEsc($fieldKey) ?>" data-dwf-register-editable="<?= $editable?'1':'0' ?>">
 <p class="dwf-register-help"><?= $wfEsc($wfI('Eine Karte je Gefährdung: Risiko vor Maßnahmen bewerten, Schutzmaßnahmen festlegen und das verbleibende Risiko prüfen. Frist und Erledigungsdatum gehören zur jeweiligen Maßnahme. Die Freigabe erledigt keine Maßnahme.')) ?></p>
 <?php if($profile!==''):?><details class="dwf-profile-original" open><summary><?= $wfEsc($wfI('Risikomatrix')) ?></summary><div class="dwf-profile-original-scroll" tabindex="0" role="region" aria-label="<?= $wfEsc($wfI('Risikomatrix')) ?>"><?= \Kulturhus\Verein\DocumentWorkflow\RiskProfiles::renderCompactLegend($profile) ?></div></details><?php endif ?>
 <div class="dwf-register-scroll" tabindex="0" role="region" aria-label="<?= $wfEsc($wfI('Gefährdungen einzeln bearbeiten')) ?>"><table class="table dwf-register-input-table"><thead><tr><?php foreach(['Nr.','Gefährdungskategorie','Gefährdung','Auswirkung']as$label):?><th scope="col" rowspan="2"><?= $wfEsc($wfI($label)) ?></th><?php endforeach ?><th scope="colgroup" colspan="3"><?= $wfEsc($wfI('Ausgangsrisiko')) ?></th><th scope="col" rowspan="2"><?= $wfEsc($wfI('Schutzmaßnahmen')) ?></th><th scope="colgroup" colspan="3"><?= $wfEsc($wfI('Restrisiko')) ?></th><th scope="col" rowspan="2"><?= $wfEsc($wfI('Verantwortlich')) ?></th><th scope="col" rowspan="2"><?= $wfEsc($wfI('Wirksamkeitsprüfung')) ?></th></tr><tr><?php for($risk=0;$risk<2;$risk++):?><th scope="col">S</th><th scope="col">L</th><th scope="col">R</th><?php endfor ?></tr></thead><tbody data-dwf-register-rows><?php foreach($registerRows as$index=>$row)$wfRegisterRow($name,$index,$row,$editable,$profile,count($registerRows),$fieldKey);?></tbody></table></div>
 <?php if($editable):?><input type="hidden" name="<?= $wfEsc('wf_register_counts['.$fieldKey.']') ?>" value="<?= count($registerRows) ?>" data-dwf-register-count-input><template data-dwf-register-row-template><?php $wfRegisterRow($name,'__ROW__',[],true,$profile,0,$fieldKey);?></template><div class="dwf-actions"><button type="submit" formnovalidate name="wf_edit" value="register_add:<?= $wfEsc($fieldKey) ?>" class="btn btn-outline theme-secondary dwf-button dwf-secondary secondary" data-dwf-register-add <?= count($registerRows)>=30?'disabled':'' ?>><?= $wfEsc($wfI('+ Gefährdungszeile hinzufügen')) ?></button><span class="dwf-muted" data-dwf-register-count><?= $wfEsc($wfF('{count} von 30 Zeilen',['count'=>count($registerRows)])) ?></span></div><p class="dwf-help"><?= $wfEsc($wfI('Zeilenaktionen verändern nur dieses offene Formular. Erst Entwurf speichern übernimmt die Änderungen.')) ?></p><?php endif ?>
 <p class="dwf-muted" role="status" aria-live="polite" data-dwf-register-status></p></section>
<?php };
